import{b as a,O as e,g as o,j as s}from"./chunks/framework.DcaUmd3X.js";const h=JSON.parse('{"title":"测试理论与实践","description":"","frontmatter":{},"headers":[],"relativePath":"testing/index.md","filePath":"测试理论与实践/index.md","lastUpdated":1781509258000}'),n={name:"testing/index.md"};function i(r,t,l,d,p,c){return e(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="测试理论与实践" tabindex="-1">测试理论与实践 <a class="header-anchor" href="#测试理论与实践" aria-label="Permalink to &quot;测试理论与实践&quot;">​</a></h1><blockquote><p>从基础理论到工程实践，系统构建测试知识体系。</p></blockquote><h2 id="教程介绍" tabindex="-1">教程介绍 <a class="header-anchor" href="#教程介绍" aria-label="Permalink to &quot;教程介绍&quot;">​</a></h2><p>教程面向想要系统学习软件测试的开发者、测试工程师和质量管理者。无论你是刚接触测试的新人，还是已有经验想补全理论框架的老手，都能在这里学到有用的内容。</p><p><strong>教程特点：</strong></p><ul><li><strong>建立完整的测试知识体系</strong>：从测试基础理论到现代工程实践，告别零散的知识点，拥有一张清晰的测试认知地图</li><li><strong>掌握可落地的测试方法</strong>：每个概念都配有具体操作方法、工具推荐和常见坑点，学完就能用</li><li><strong>提升测试思维深度</strong>：学会像资深测试工程师一样思考——不只是&quot;怎么测&quot;，更是&quot;为什么要这样测&quot;&quot;哪里最值得测&quot;</li><li><strong>理解测试在工程中的位置</strong>：从敏捷测试到持续交付，看清测试如何融入整个软件开发生命周期</li><li><strong>补齐软技能短板</strong>：风险管理、团队协作、测试文化建设，不止会干活，还能推动团队质量提升</li></ul><h2 id="学习路线图" tabindex="-1">学习路线图 <a class="header-anchor" href="#学习路线图" aria-label="Permalink to &quot;学习路线图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基础认知 ─→ 执行过程 ─→ 方法体系 ─→ 现代测试工程 ─→ 风险管理 ─→ 总结展望</span></span></code></pre></div>',8)])])}const g=a(n,[["render",i]]);export{h as __pageData,g as default};
